784	Error RewriteInstance::run() {
785	  assert(BC && "failed to create a binary context");
786	
787	  BC->outs() << "BOLT-INFO: Target architecture: "
788	             << Triple::getArchTypeName(
789	                    (llvm::Triple::ArchType)InputFile->getArch())
790	             << "\n";
791	  BC->outs() << "BOLT-INFO: BOLT version: " << BoltRevision << "\n";
792	
793	  selectFunctionsToPrint();
794	
795	  if (Error E = discoverStorage())
796	    return E;
797	  if (Error E = readSpecialSections())
798	    return E;
799	  adjustCommandLineOptions();
800	  discoverFileObjects();
801	
802	  if (opts::Instrument && !BC->IsStaticExecutable) {
803	    if (Error E = discoverRtInitAddress())
804	      return E;
805	    if (Error E = discoverRtFiniAddress())
806	      return E;
807	  }
808	
809	  preprocessProfileData();
810	
811	  selectFunctionsToProcess();
812	
813	  readDebugInfo();
814	
815	  disassembleFunctions();
816	
817	  processMetadataPreCFG();
818	
819	  buildFunctionsCFG();
820	
821	  processProfileData();
822	
823	  // Save input binary metadata if BAT section needs to be emitted
824	  if (opts::EnableBAT)
825	    BAT->saveMetadata(*BC);
826	
