172	bool HeatmapBlockSpecParser::parse(cl::Option &O, StringRef ArgName,
173	                                   StringRef Arg, HeatmapBlockSizes &Val) {
174	  // Parses a human-readable suffix into a shift amount or nullopt on error.
175	  auto parseSuffix = [](StringRef Suffix) -> std::optional<unsigned> {
176	    if (Suffix.empty())
177	      return 0;
178	    if (!Regex{"^[kKmMgG]i?[bB]?$"}.match(Suffix))
179	      return std::nullopt;
180	    // clang-format off
181	    switch (Suffix.front()) {
182	      case 'k': case 'K': return 10;
183	      case 'm': case 'M': return 20;
184	      case 'g': case 'G': return 30;
185	    }
186	    // clang-format on
187	    llvm_unreachable("Unexpected suffix");
188	  };
189	
190	  SmallVector<StringRef> Sizes;
191	  Arg.split(Sizes, ',');
192	  unsigned PreviousSize = 0;
193	  for (StringRef Size : Sizes) {
194	    StringRef OrigSize = Size;
195	    unsigned &SizeVal = Val.emplace_back(0);
196	    if (Size.consumeInteger(10, SizeVal)) {
197	      O.error("'" + OrigSize + "' value can't be parsed as an integer");
198	      return true;
199	    }
200	    if (std::optional<unsigned> ShiftAmt = parseSuffix(Size)) {
201	      SizeVal <<= *ShiftAmt;
202	    } else {
203	      O.error("'" + Size + "' value can't be parsed as a suffix");
204	      return true;
205	    }
206	    if (SizeVal <= PreviousSize || (PreviousSize && SizeVal % PreviousSize)) {
207	      O.error("'" + OrigSize + "' must be a multiple of previous value");
208	      return true;
209	    }
210	    PreviousSize = SizeVal;
211	  }
212	  return false;
213	}
